function splitInteractivePoints(text: string): string[] {   if (!text) return [];   const normalizedText = text.replace(/\\n/g, "\n");
  const rawLines = normalizedText.split(/(?:\r?\n|•|\.(?=\s+[A-Z0-9\u0600-\u06FF]))/g).map(s => s.trim().replace(/^[•\-–—]+\s*/, "")).filter(s => s.length > 2);   const processed: string[] = [];   let lastHeaderPrefix = "";
  for (const rawItem of rawLines) {     const headerMatch = rawItem.match(/^([A-Za-z\u0600-\u06FF0-9\s/&()\-]{3,32}):\s+(.+)$/);     if (headerMatch) {
      lastHeaderPrefix = headerMatch[1]!.trim();     }     if (rawItem.includes(";") && rawItem.length > 110) {
      const semiParts = rawItem.split(";").map(p => p.trim()).filter(p => p.length > 2);       semiParts.forEach((sp, idx) => {         if (idx === 0) {
          processed.push(sp);         } else if (/^[A-Za-z\u0600-\u06FF0-9\s/&()\-]{3,30}:/.test(sp)) {           processed.push(sp);
        } else {           const cap = sp.charAt(0).toUpperCase() + sp.slice(1);           processed.push(lastHeaderPrefix ? `${lastHeaderPrefix} — ${cap}` : cap);
        }       });     } else {
      const cap = rawItem.charAt(0).toUpperCase() + rawItem.slice(1);       processed.push(cap);     }
  }   const unique: string[] = [];   const seen = new Set<string>();
  for (const item of processed) {     const norm = item.toLowerCase().replace(/\s+/g, " ").trim();     if (!seen.has(norm)) {
      seen.add(norm);       unique.push(item);     }
  }   return unique.length > 0 ? unique : [normalizedText]; }
